#!/bin/bash
# Batch entry point included in reproducible study snapshots.
set -euo pipefail
REPO=${SLURM_SUBMIT_DIR:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)}
cd "$REPO"
# This file is generated by scripts/package_cluster.py with shell-quoted values.
source configs/cluster-runtime.env
: "${WORK:?missing WORK}" "${SIF:?missing SIF}" "${MODEL_DIR:?missing MODEL_DIR}" "${SERVED_NAME:?missing SERVED_NAME}"
RUN_ROOT=$(dirname "$REPO")
export PATH=$WORK/tools/uv-x86_64-unknown-linux-gnu:$PATH
export UV_CACHE_DIR=$WORK/cache/uv
export SIF MODEL_DIR SERVED_NAME MAX_MODEL_LEN PORT VLLM_EXTRA_ARGS
export CONFIG=configs/experiment.yaml
export LOG_DIR=$RUN_ROOT/logs
export VLLM_CACHE_ROOT=$WORK/cache/vllm
test -f "$SIF"
test -d "$MODEL_DIR"
command -v uv >/dev/null
mkdir -p "$LOG_DIR"
hostname
nvidia-smi --query-gpu=name,driver_version,memory.total --format=csv,noheader
DRIVER=$(nvidia-smi --query-gpu=driver_version --format=csv,noheader | head -1)
CUDA=$(nvidia-smi | sed -n 's/.*CUDA Version: *\([0-9.]*\).*/\1/p' | head -1)
if [ "${CUDA%%.*}" -lt 13 ]; then
    case "${DRIVER%%.*}" in
        535|570)
            apptainer exec --cleanenv "$SIF" test -f /usr/local/cuda/compat/libcuda.so.1
            export APPTAINERENV_VLLM_ENABLE_CUDA_COMPATIBILITY=1
            export APPTAINERENV_LD_LIBRARY_PATH=/usr/local/cuda/compat:/.singularity.d/libs
            export MIN_CUDA_MAJOR=0
            ;;
        *) echo "Unsupported driver $DRIVER for the pinned CUDA 13 image"; exit 1 ;;
    esac
fi
git rev-parse HEAD
printf 'MODEL_DIR=%s SERVED_NAME=%s REVISION=%s\n' "$MODEL_DIR" "$SERVED_NAME" "$MODEL_REVISION"
if [ -n "${MODEL_PROVENANCE:-}" ]; then cat "$MODEL_PROVENANCE"; fi
if [ -f "$SIF.sha256" ]; then cat "$SIF.sha256"; fi
uv sync --locked
uv run --locked python -m passgame.run --config "$CONFIG" --preflight
exec bash scripts/cluster/serve_and_eval.sh
